use crate::aap::caps::state_read;

/// Key within the `subscriptions` store holding the newline-separated feed URLs.
const URLS_KEY: &str = "urls";

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        // A missing key yields an empty list, which is still a present `urls`
        // field. Blank lines and surrounding whitespace are dropped.
        let urls: Vec<String> = match state_read::get(URLS_KEY) {
            Some(raw) => raw
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
